program:
// Newton Cenotaph (Boullee): hollow geodesic sphere on stepped drums with cypress rings. Z-up, mm.
// variant 1 = closed shell with star openings, 2 = front cutaway (default). freq = geodesic frequency.
variant = 2;
freq = 6;
R = 50;  T = 2.5;                 // sphere outer radius, wall thickness
DC = 60;                          // sphere centre height

// ---- geodesic sphere: icosahedron subdivided `freq` times, as a list of unit-vector triangles ----
phi = (1 + sqrt(5)) / 2;
function nrm(v) = v / norm(v);
IV = [for (p = [[-1,phi,0],[1,phi,0],[-1,-phi,0],[1,-phi,0],[0,-1,phi],[0,1,phi],[0,-1,-phi],[0,1,-phi],[phi,0,-1],[phi,0,1],[-phi,0,-1],[-phi,0,1]]) nrm(p)];
IF = [[0,11,5],[0,5,1],[0,1,7],[0,7,10],[0,10,11],[1,5,9],[5,11,4],[11,10,2],[10,7,6],[7,1,8],[3,9,4],[3,4,2],[3,2,6],[3,6,8],[3,8,9],[4,9,5],[2,4,11],[6,2,10],[8,6,7],[9,8,1]];
function gp(A,B,C,f,i,j) = nrm(A + (B-A)*i/f + (C-A)*j/f);
function tris(f) = [for (fc = IF) let(A = IV[fc[0]], B = IV[fc[1]], C = IV[fc[2]])
  each [for (i = [0:f-1]) for (j = [0:f-1-i]) each concat(
    [[gp(A,B,C,f,i,j), gp(A,B,C,f,i+1,j), gp(A,B,C,f,i,j+1)]],
    (i + j <= f-2) ? [[gp(A,B,C,f,i+1,j), gp(A,B,C,f,i+1,j+1), gp(A,B,C,f,i,j+1)]] : [])]];
TR = tris(freq);

// triangular prism between radius ri and ro (top triangle inset toward its centre by factor s)
module cell(t, ro, ri, s = 1) {
  g = (t[0] + t[1] + t[2]) / 3 * ro;
  o = [for (k = [0:2]) g + (t[k]*ro - g) * s];
  polyhedron(points = concat(o, [for (k = [0:2]) t[k]*ri]),
             faces = [[0,2,1],[3,4,5],[0,1,4,3],[1,2,5,4],[2,0,3,5]]);
}

// which cells exist: variant 2 cuts a cone out of the front (-y); variant 1 punches every 13th facet
function cut(i) = (variant == 2) ? (nrm(TR[i][0]+TR[i][1]+TR[i][2]) * nrm([0,-1,0.1]) > 0.62) : (i % 13 == 0);

module shell()   { translate([0,0,DC]) for (i = [0:len(TR)-1]) if (!cut(i)) cell(TR[i], R, R - T); }
module lining()  { translate([0,0,DC]) for (i = [0:len(TR)-1]) if (!cut(i)) cell(TR[i], R - T, R - T - 0.4); }
module stars()   { translate([0,0,DC]) for (i = [0:len(TR)-1]) if (!cut(i) && i % 6 == 0) cell(TR[i], R - T - 0.4, R - T - 0.7); }

// ---- base ----
module disc(r, z, h, n = 40) translate([0,0,z]) cylinder(r = r, h = h, $fn = n);
module base() { disc(92, 0, 9); disc(78, 9, 5); disc(66, 14, 4); }

module cypress(x, y, z)
  translate([x, y, z]) rotate_extrude($fn = 5) polygon([[0,0],[0.3,0],[1.7,4.25],[1.3,10.2],[0.05,17],[0,17]]);
module trees() {
  for (i = [0:55]) { a = i / 56 * 360; if (!(a > 260 && a < 280)) cypress(85*cos(a), 85*sin(a), 9); }   // gap at the entrance (-y)
  for (i = [0:45]) { a = (i + 0.5) / 46 * 360; cypress(71*cos(a), 71*sin(a), 14); }
}

module bx(c, z, w, d, h) translate([c[0], c[1], z]) translate([-w/2, -d/2, 0]) cube([w, d, h]);
module portal() { bx([-7.5,-91], 0, 4, 5, 9.5); bx([7.5,-91], 0, 4, 5, 9.5); bx([0,-91], 8.2, 19, 5, 2.2);
                  bx([0,-97], 0, 22, 6, 1.5); bx([0,-94], 0, 20, 4, 3); }
module door()  { bx([0,-90.2], 0, 11, 4, 8.2); }

// ---- interior: floor, brass armillary on a chain ----
module floor_disc() disc(24, 18.35, 0.4, 24);   // lifted a hair off the plinth top (z=18) to kill the coplanar z-fight
module armillary() {
  translate([0,0,DC-15]) {
    for (o = [[0,0,0],[90,0,0],[90,90,0],[45,45,0]]) rotate(o) rotate_extrude($fn = 16) translate([13,0]) circle(r = 0.55, $fn = 4);
    sphere(r = 4, $fn = 8);
  }
  translate([0,0,DC-2]) cylinder(r = 0.35, h = R + 1, $fn = 4);
}
